function BwPracticeMenu({test, passage, exercise = false, onSaved}) {
  const [open, setOpen] = R.useState(false);
  const [saving, setSaving] = R.useState(false);
  const busy = R.useRef(false);
  const root = R.useRef(null);
  const trigger = R.useRef(null);
  const action = R.useRef(null);
  const id = R.useId();
  const practised = test.is_practised ?? (exercise ? test.times_done > 0 : test.practised_count > 0);
  const title = exercise ? `${test.test_title}, ${test.section_title || `section ${test.section}`}` : test.title;
  const label = practised ? 'Mark as not practised' : 'Mark as practised';
  R.useEffect(() => {
    if (!open) return;
    action.current?.focus();
    const outside = event => { if (!root.current?.contains(event.target)) setOpen(false); };
    const key = event => {
      if (event.key === 'Escape') { event.preventDefault(); setOpen(false); trigger.current?.focus(); }
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp' || event.key === 'Home' || event.key === 'End') {
        if (root.current?.contains(event.target)) { event.preventDefault(); action.current?.focus(); }
      }
      if (event.key === 'Tab') setOpen(false);
    };
    document.addEventListener('pointerdown', outside);
    document.addEventListener('keydown', key);
    return () => { document.removeEventListener('pointerdown', outside); document.removeEventListener('keydown', key); };
  }, [open]);
  const toggle = async () => {
    if (busy.current) return;
    busy.current = true;
    setSaving(true);
    try {
      const endpoint = exercise ? `/me/exercises/${test.id}/practice-status` : `/me/library/${test.id}/practice-status`;
      await me.put(endpoint, {is_practised:!practised, ...(!exercise ? {passage:test.module === 'reading' && passage ? Number(passage) : null} : {})});
      setOpen(false);
      trigger.current?.focus();
      await onSaved();
      vt(practised ? 'Marked as not practised' : 'Marked as practised');
    } catch (error) {
      vt(bt(error), 'error');
    } finally {
      busy.current = false;
      setSaving(false);
    }
  };
  return l.jsxs('div', {className:'bw-practice-menu', ref:root, children:[
    l.jsx('button', {ref:trigger, type:'button', className:'bw-practice-menu-trigger', 'aria-label':`More options: ${title}`,
      'aria-haspopup':'menu', 'aria-expanded':open, 'aria-controls':open ? id : undefined,
      onClick:() => setOpen(value => !value),
      onKeyDown:event => { if (event.key === 'ArrowDown' || event.key === 'ArrowUp') { event.preventDefault(); setOpen(true); } },
      children:l.jsx('span', {'aria-hidden':true, children:'⋮'})}),
    open && l.jsx('div', {id, role:'menu', 'aria-label':`Practice status: ${title}`, className:'bw-practice-menu-popup', children:
      l.jsx('button', {ref:action, type:'button', role:'menuitem', disabled:saving, 'aria-busy':saving, onClick:toggle,
        children:saving ? 'Saving…' : label})})
  ]});
}

