function BwContinueSection({data}) {
  const navigate = nr();
  const [busy, setBusy] = R.useState(false);
  const pending = R.useRef(false);
  if (data.next_section_position == null) return null;
  const label = data.test.module === 'reading' ? 'passage' : 'part';
  const next = async () => {
    if (pending.current) return;
    pending.current = true; setBusy(true);
    try {
      const {data: target} = await me.post('/exams/start', {continue_from: data.attempt.id});
      navigate(target.finished ? `/results/${target.attempt_id}` : `/exam/${target.attempt_id}`);
    } catch (error) { vt(bt(error), 'error'); }
    finally { pending.current = false; setBusy(false); }
  };
  return l.jsx('button', {type:'button', className:'btn-primary', disabled:busy, onClick:next,
    children:busy ? 'Opening…' : `Continue to ${label} ${data.next_section_position}`});
}

// Store the stable section ID, not its index. Use the first valid section if a
// bookmark is absent/stale. This only affects full Reading and Listening attempts.
function useBwSection(attemptId, data) {
  const [ordinary, setOrdinary] = R.useState(0);
  const key = `bw-section-${attemptId}`;
  const read = () => { try { return localStorage.getItem(key); } catch { return null; } };
  const [saved, setSaved] = R.useState(() => ({key, id:read()}));
  const sections = data?.test?.sections || [];
  if (!['reading','listening'].includes(data?.test?.module)) return [ordinary,setOrdinary];
  const id = saved.key === key ? saved.id : read();
  const index = Math.max(0, sections.findIndex(section => String(section.id) === id));
  return [index, nextIndex => {
    const section = sections[nextIndex];
    if (!section) return;
    const id = String(section.id);
    try { localStorage.setItem(key, id); } catch {}
    setSaved({key,id});
  }];
}

